const now=ref(Date.now())
// Conta da sessão (null na demonstração sem conta). O nome e o botão Sair vêm daqui.
const account=ref(null)
fetch('/api/auth/status',{headers:{Accept:'application/json'}}).then(r=>r.json()).then(s=>{account.value=s.user||null}).catch(()=>{})
const signingOut=ref(false)
async function leave(){if(signingOut.value)return;signingOut.value=true;try{await signOut()}catch(e){notify(e.message,'error');signingOut.value=false}}
const route=ref('inicio'), collapsed=ref(false), mobileMenu=ref(false), search=ref(''), taskFilter=ref('open')
const data=ref({entries:[],checkins:[],events:[],sources:{}}), tasks=ref([]), projects=ref([]), online=ref(navigator.onLine), loading=ref(true), refreshing=ref(false), error=ref(''), notice=ref('')
const proofDialog=ref(null), proofSaving=ref(false)
const saveState=computed(()=>!online.value||error.value?'offline':saving.value||proofSaving.value?'saving':'saved')
const domains=[['saude','Saúde'],['alimentacao','Alimentação'],['financas','Finanças'],['estudos','Estudos'],['mente','Mente'],['organizacao','Organização']]
const routeDomain={fitness:'saude',nutricao:'alimentacao',financas:'financas',estudos:'estudos',biblioteca:'estudos',autoconhecimento:'mente'}
const modal=ref(null), saving=ref(false)
const form=ref({title:'',body:'',amount:'',direction:'expense',category:'pessoal',day:'',due_date:''})
let poll, timer, previousFocus
const weightMinDay=()=>{const d=new Date(today()+'T12:00:00');d.setDate(d.getDate()-120);return d.toISOString().slice(0,10)}
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(now.value))
const shortDate=computed(()=>new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',weekday:'long',day:'numeric',month:'long'}).format(new Date(now.value)))
const greeting=computed(()=>{const hour=Number(new Intl.DateTimeFormat('en-GB',{timeZone:'America/Sao_Paulo',hour:'2-digit',hourCycle:'h23'}).format(new Date(now.value)));const who=account.value?.display_name?.split(' ')[0];const hello=hour<12?'Bom dia':hour<18?'Boa tarde':'Boa noite';return who?`${hello}, ${who}.`:`${hello}.`})
const active=computed(()=>sections.find(i=>i.id===route.value))
const entryList=kind=>data.value.entries.filter(i=>i.kind===kind)
const habits=computed(()=>entryList('habit'))
const goals=computed(()=>entryList('goal'))
const goalCount=id=>data.value.checkins.filter(i=>i.entry_id===id&&i.done===1).length
const isDone=ident=>data.value.checkins.some(i=>i.entry_id===ident&&i.day===today()&&i.done===1)
const habitsDone=computed(()=>habits.value.filter(i=>isDone(i.id)).length)
const pending=computed(()=>tasks.value.filter(i=>i.status!=='done'&&!i.completed_at))
const shownTasks=computed(()=>tasks.value.filter(i=>(taskFilter.value==='all'||(taskFilter.value==='open'?i.status!=='done':i.status==='done'))&&(!search.value||String(i.title).toLowerCase().includes(search.value.toLowerCase()))))
// Peso real (etapa 5): uma pesagem por dia e a média móvel de 7 dias, sem meta e sem julgamento.
const weightDialog=ref(null), confirmWeight=ref('')
const weights=computed(()=>data.value.weights||[]), trend=computed(()=>data.value.weight_trend||[])
const kg=grams=>new Intl.NumberFormat('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1}).format(grams/1000)
const latestTrend=computed(()=>trend.value.at(-1))
const trendText=computed(()=>({estavel:'Sua média está estável nas últimas 2 semanas.',subindo:'Sua média está um pouco mais alta que há 2 semanas.',descendo:'Sua média está um pouco mais baixa que há 2 semanas.'})[data.value.weight_direction]||(trend.value.length?'Com mais algumas pesagens, a tendência aparece aqui.':'Seu gráfico começa com a primeira pesagem.'))
const chart=computed(()=>{const pts=trend.value;if(!pts.length)return null;const W=320,H=140,pad={l:8,r:8,t:12,b:20};const time=d=>Date.parse(d+'T12:00:00Z');const t0=time(pts[0].day),t1=time(pts.at(-1).day);const values=pts.flatMap(p=>[p.grams,p.avg_grams]);let lo=Math.min(...values),hi=Math.max(...values);if(hi-lo<1000){const mid=(hi+lo)/2;lo=mid-500;hi=mid+500}const x=p=>pad.l+(t1===t0?(W-pad.l-pad.r)/2:(time(p.day)-t0)/(t1-t0)*(W-pad.l-pad.r));const y=g=>pad.t+(hi-g)/(hi-lo)*(H-pad.t-pad.b);return{W,H,lo,hi,dots:pts.map(p=>({cx:x(p),cy:y(p.grams),day:p.day})),line:pts.map((p,i)=>`${i?'L':'M'}${x(p).toFixed(1)} ${y(p.avg_grams).toFixed(1)}`).join(''),from:pts[0].day,to:pts.at(-1).day,label:`Gráfico de peso: ${pts.length} pesagens, de ${kg(Math.min(...pts.map(p=>p.grams)))} a ${kg(Math.max(...pts.map(p=>p.grams)))} kg, com a média de 7 dias.`}})
function showWeight(w){previousFocus=document.activeElement;weightDialog.value=w?{id:w.id,day:w.day,kg:String(w.grams/1000).replace('.',','),note:w.note}:{id:null,day:today(),kg:weights.value[0]?String(weights.value[0].grams/1000).replace('.',','):'',note:''};nextTick(()=>document.querySelector('.side-dialog input:not(:disabled)')?.focus())}
function closeWeight(){if(saving.value)return;weightDialog.value=null;previousFocus?.focus?.()}
async function saveWeight(){const d=weightDialog.value;if(!d||saving.value)return;const value=Number(String(d.kg).trim().replace(',','.'));const grams=Math.round(value*1000);if(!Number.isFinite(value)||grams<20000||grams>400000){notify('Informe um peso entre 20 e 400 kg.','error');return}saving.value=true;try{const note=d.note.trim();applyOverview(d.id?await editWeight(d.id,{grams,note}):await addWeight({day:d.day,grams,note}));weightDialog.value=null;notify(d.id?'Pesagem atualizada.':'Pesagem registrada.');previousFocus?.focus?.()}catch(e){notify(e.message,'error')}finally{saving.value=false}}
async function dropWeight(w){if(saving.value)return;if(confirmWeight.value!==w.id){confirmWeight.value=w.id;return}saving.value=true;try{applyOverview(await removeWeight(w.id));confirmWeight.value='';notify('Pesagem apagada.')}catch(e){notify(e.message,'error')}finally{saving.value=false}}
// Agenda real (etapa 5): compromissos e dias de respiro vêm de /api/personal, um mês por vez.
// Projetos reais (etapa 5): um nome e um próximo passo, sem prazo.
const projectView=ref('active'), projectDialog=ref(null), stepDrafts=ref({}), confirmProject=ref('')
const shownProjects=computed(()=>projects.value.filter(i=>i.status===projectView.value))
const activeCount=computed(()=>projects.value.filter(i=>i.status==='active').length)
const savedCount=computed(()=>projects.value.filter(i=>i.status==='archived').length)
const draftOf=p=>stepDrafts.value[p.id]??p.next_step??''
const dirtyStep=p=>draftOf(p).trim()!==(p.next_step||'')
const stepsLabel=n=>`${n} passo${n===1?'':'s'} dado${n===1?'':'s'}`
const stepPrompt=p=>!p.next_step&&p.steps_done>0?'E agora, qual é o próximo?':'Qual é o próximo passo?'
const agendaMonth=ref(''), selectedDay=ref(''), eventDialog=ref(null), confirmEvent=ref('')
const monthOfToday=()=>today().slice(0,7)
const viewMonth=()=>route.value==='agenda'&&agendaMonth.value?agendaMonth.value:monthOfToday()
const monthEvents=computed(()=>data.value.events_month===agendaMonth.value?data.value.events||[]:[])
const eventsOn=day=>monthEvents.value.filter(i=>i.day===day)
const todayEvents=computed(()=>(data.value.events||[]).filter(i=>i.day===today()))
const todayRespiro=computed(()=>todayEvents.value.some(i=>i.kind==='respiro'))
const monthLabel=computed(()=>agendaMonth.value?new Intl.DateTimeFormat('pt-BR',{timeZone:'UTC',month:'long',year:'numeric'}).format(new Date(agendaMonth.value+'-01T12:00:00Z')):'')
const monthCells=computed(()=>{if(!agendaMonth.value)return[];const[y,m]=agendaMonth.value.split('-').map(Number);const blanks=(new Date(Date.UTC(y,m-1,1)).getUTCDay()+6)%7;const total=new Date(Date.UTC(y,m,0)).getUTCDate();return[...Array(blanks).fill(null),...Array.from({length:total},(_,i)=>{const day=`${agendaMonth.value}-${String(i+1).padStart(2,'0')}`;return{day,num:i+1,events:eventsOn(day)}})]})
const selectedEvents=computed(()=>eventsOn(selectedDay.value))
const selectedRespiro=computed(()=>selectedEvents.value.find(i=>i.kind==='respiro'))
const longDay=day=>day?new Intl.DateTimeFormat('pt-BR',{timeZone:'UTC',weekday:'long',day:'numeric',month:'long'}).format(new Date(day+'T12:00:00Z')):''
const eventTime=e=>e.kind==='respiro'?'Respiro':e.start_time?(e.end_time?`${e.start_time}–${e.end_time}`:e.start_time):'Dia todo'
const cellClass=cell=>({'is-respiro':cell.events.some(i=>i.kind==='respiro'),'has-event':cell.events.some(i=>i.kind!=='respiro'),today:cell.day===today(),selected:cell.day===selectedDay.value,past:cell.day<today()})
const cellLabel=cell=>{const n=cell.events.filter(i=>i.kind!=='respiro').length;return `${cell.num} de ${monthLabel.value}: ${cell.events.some(i=>i.kind==='respiro')?'dia de respiro':n?`${n} compromisso${n===1?'':'s'}`:'dia livre'}`}
const notes=computed(()=>entryList('note')), transactions=computed(()=>entryList('transaction'))
const monthTransactions=computed(()=>transactions.value.filter(i=>i.day.slice(0,7)===today().slice(0,7)))
const income=computed(()=>monthTransactions.value.filter(i=>i.direction==='income').reduce((s,i)=>s+i.amount_cents,0))
const expenses=computed(()=>monthTransactions.value.filter(i=>i.direction==='expense').reduce((s,i)=>s+i.amount_cents,0))
const money=cents=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(cents/100)
const formatDate=day=>day?new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(day.slice(0,10)+'T12:00:00')):'Sem data'
const match=q=>!search.value||String(q||'').toLowerCase().includes(search.value.toLowerCase())
const weeks=computed(()=>{const d=new Date(today()+'T12:00:00');const offset=(d.getDay()+6)%7;return Array.from({length:7},(_,i)=>{const n=new Date(d);n.setDate(d.getDate()-offset+i);const key=`${n.getFullYear()}-${String(n.getMonth()+1).padStart(2,'0')}-${String(n.getDate()).padStart(2,'0')}`;return{day:key,num:n.getDate(),label:['S','T','Q','Q','S','S','D'][i],today:key===today()}})})
const areaCards=computed(()=>[
{id:'habitos',icon:'habits',tone:'mint',title:'Seja constante',value:habits.value.length?`${habitsDone.value} de ${habits.value.length}`:'Seu primeiro hábito',detail:habits.value.length?'passos dados hoje':'Comece com dois minutos'},
{id:'fitness',icon:'fitness',tone:'peach',title:'Cuide de você',value:weights.value.length?`${kg(weights.value[0].grams)} kg`:'Sua evolução',detail:'Treino, trajetória e recuperação'},
{id:'financas',icon:'finance',tone:'purple',title:'Respire mais leve',value:transactions.value.length?money(income.value-expenses.value):'Sua vida financeira',detail:transactions.value.length?'saldo dos registros deste mês':'Entradas e saídas, com clareza'},
{id:'estudos',icon:'study',tone:'blue',title:'Continue aprendendo',value:'Seus materiais',detail:'Em breve, neste mesmo lugar'}])
function notify(text,kind='success'){notice.value={text,kind};clearTimeout(timer);timer=setTimeout(()=>notice.value='',4500)}
function parseRoute(){const id=location.hash.replace(/^#\/?/,'').split('/')[0];route.value=sections.some(i=>i.id===id)||id==='cidade'||id==='mundo'?id:'inicio';if(route.value==='agenda'&&!agendaMonth.value){agendaMonth.value=monthOfToday();selectedDay.value=today()}search.value='';mobileMenu.value=false;if(data.value.events_month&&data.value.events_month!==viewMonth())refresh();document.title=(route.value==='cidade'?'Minha cidade':route.value==='mundo'?'Mapa-mundo':active.value?.label||'Seu espaço')+' · Cityou'}
function navigate(id){location.hash='/'+id}
async function refresh() {
  if (refreshing.value) return
  refreshing.value = true
  now.value = Date.now()
  error.value = ''
  const [personal] = await Promise.allSettled([api(`/api/personal?month=${viewMonth()}`)])
  if (personal.status === 'fulfilled') {
    data.value = personal.value
    // Tarefas reais, guardadas na conta ou na demonstração deste navegador (etapa 2), vêm na mesma leitura.
    tasks.value = personal.value.tasks || []
    projects.value = personal.value.projects || []
  } else {
    error.value = personal.reason?.status === 404
      ? 'Os registros pessoais precisam do servidor Cityou, que não está disponível neste endereço.'
      : 'Não foi possível carregar seus registros. Tente atualizar.'
  }
  loading.value = false
  refreshing.value = false
  // A pessoa trocou de mês enquanto o pedido ia: busca o mês certo.
  if (personal.status === 'fulfilled' && personal.value.events_month && personal.value.events_month !== viewMonth()) refresh()
}
function applyOverview(result){const {created_id,...rest}=result;data.value={...data.value,...rest};if(rest.tasks)tasks.value=rest.tasks;if(rest.projects)projects.value=rest.projects}
async function shiftMonth(delta){const[y,m]=agendaMonth.value.split('-').map(Number);agendaMonth.value=new Date(Date.UTC(y,m-1+delta,1)).toISOString().slice(0,7);selectedDay.value=agendaMonth.value===monthOfToday()?today():agendaMonth.value+'-01';confirmEvent.value='';await refresh()}
async function projectCall(work,message){if(saving.value)return;saving.value=true;try{applyOverview(await work());if(message)notify(message);return true}catch(e){notify(e.message,'error')}finally{saving.value=false}}
async function saveStep(p){const step=draftOf(p).trim();if(await projectCall(()=>editProject(p.id,{next_step:step||null}),step?'Próximo passo guardado.':'')){const{[p.id]:_,...rest}=stepDrafts.value;stepDrafts.value=rest}}
async function finishStep(p){if(await projectCall(()=>stepDone(p.id),'Passo dado. Um de cada vez já é caminho.')){const{[p.id]:_,...rest}=stepDrafts.value;stepDrafts.value=rest}}
function setProjectStatus(p,status){return projectCall(()=>editProject(p.id,{status}),status==='archived'?'Guardado por enquanto. Volta quando você quiser.':'Projeto retomado.')}
async function dropProject(p){if(confirmProject.value!==p.id){confirmProject.value=p.id;return}if(await projectCall(()=>removeProject(p.id),'Projeto apagado.'))confirmProject.value=''}
function showProject(p){previousFocus=document.activeElement;projectDialog.value=p?{id:p.id,name:p.name,description:p.description}:{id:null,name:'',description:'',next_step:''};nextTick(()=>document.querySelector('.side-dialog input')?.focus())}
function closeProject(){if(saving.value)return;projectDialog.value=null;previousFocus?.focus?.()}
async function saveProject(){const d=projectDialog.value;if(!d)return;const{id,...fields}=d;if(!id)fields.next_step=fields.next_step?.trim()||null;if(await projectCall(()=>id?editProject(id,fields):addProject(fields),id?'Projeto atualizado.':'Projeto criado.')){projectDialog.value=null;previousFocus?.focus?.()}}
function showEvent(event){previousFocus=document.activeElement;eventDialog.value=event?{id:event.id,title:event.title,day:event.day,start_time:event.start_time||'',end_time:event.end_time||'',firmness:event.firmness,place:event.place,notes:event.notes}:{id:null,title:'',day:selectedDay.value||today(),start_time:'',end_time:'',firmness:'firme',place:'',notes:''};nextTick(()=>document.querySelector('.side-dialog input')?.focus())}
function closeEvent(){if(saving.value)return;eventDialog.value=null;previousFocus?.focus?.()}
async function saveEvent(){const dialog=eventDialog.value;if(!dialog||saving.value)return;saving.value=true;try{const{id,...fields}=dialog;const body={...fields,start_time:fields.start_time||null,end_time:fields.end_time||null};applyOverview(id?await editEvent(id,body,viewMonth()):await addEvent(body,viewMonth()));eventDialog.value=null;notify(id?'Compromisso atualizado.':'Compromisso guardado.');if(route.value==='agenda'){selectedDay.value=body.day;if(body.day.slice(0,7)!==agendaMonth.value){agendaMonth.value=body.day.slice(0,7);await refresh()}}previousFocus?.focus?.()}catch(e){notify(e.message,'error')}finally{saving.value=false}}
async function toggleRespiro(day){if(saving.value||!day)return;saving.value=true;try{const found=eventsOn(day).find(i=>i.kind==='respiro');applyOverview(found?await removeEvent(found.id,viewMonth()):await addEvent({kind:'respiro',day},viewMonth()));notify(found?'Respiro retirado.':'Dia de respiro marcado. Nada a cumprir.')}catch(e){notify(e.message,'error')}finally{saving.value=false}}
async function dropEvent(event){if(saving.value)return;if(confirmEvent.value!==event.id){confirmEvent.value=event.id;return}saving.value=true;try{applyOverview(await removeEvent(event.id,viewMonth()));confirmEvent.value='';notify('Compromisso apagado.')}catch(e){notify(e.message,'error')}finally{saving.value=false}}
function showForm(kind){previousFocus=document.activeElement;modal.value=kind;form.value={title:'',body:'',amount:'',direction:'expense',category:'pessoal',day:today(),due_date:'',target:1,domain:routeDomain[route.value]||'organizacao',place:''};nextTick(()=>document.querySelector('.entry-dialog input')?.focus())}
function closeForm(){if(saving.value)return;modal.value=null;previousFocus?.focus?.()}
async function save(){if(saving.value)return;saving.value=true;try{if(modal.value==='task'){await api('/api/personal/tasks','POST',{title:form.value.title,due_date:form.value.due_date||null,domain:form.value.domain,place:form.value.place});notify('Tarefa salva.')}else{const raw=String(form.value.amount).trim().replace(/^R\$\s*/, '').replace(/\s/g,'');const normalized=/^\d{1,3}(?:\.\d{3})+(?:,\d{1,2})?$/.test(raw)?raw.replace(/\./g,'').replace(',','.'):/^\d+(?:[,.]\d{1,2})?$/.test(raw)?raw.replace(',','.'):'invalid';const cents=Math.round(Number(normalized)*100);if(modal.value==='transaction'&&(!Number.isFinite(cents)||cents<1))throw Error('Informe um valor válido.');await api('/api/personal/entries','POST',{kind:modal.value,title:form.value.title,body:form.value.body,category:form.value.category,day:form.value.day,direction:form.value.direction,amount_cents:modal.value==='transaction'?cents:0,target:modal.value==='goal'?Number(form.value.target):1,domain:form.value.domain,place:form.value.place});notify('Registro salvo.')}modal.value=null;await refresh();previousFocus?.focus?.()}catch(e){notify(e.message,'error')}finally{saving.value=false}}
async function toggleHabit(item){if(saving.value)return;saving.value=true;try{const result=await api(`/api/personal/entries/${encodeURIComponent(item.id)}/checkin`,'PUT',{done:!isDone(item.id)});data.value={...data.value,...result};notify(isDone(item.id)?'Passo de hoje registrado.':'Registro de hoje desmarcado.')}catch(e){notify(e.message,'error')}finally{saving.value=false}}
async function finish(task){if(saving.value)return;saving.value=true;try{await completeTask(task.id);notify('Tarefa concluída. Seu progresso também chega à cidade.');await refresh()}catch(e){notify(e.message,'error')}finally{saving.value=false}}
function showProof(item){previousFocus=document.activeElement;proofDialog.value={item,note:'',file:null,preview:''};nextTick(()=>document.querySelector('.proof-dialog textarea')?.focus())}
function closeProof(){if(proofSaving.value)return;if(proofDialog.value?.preview)URL.revokeObjectURL(proofDialog.value.preview);proofDialog.value=null;previousFocus?.focus?.()}
function pickPhoto(event){const file=event.target.files?.[0];if(!file)return;if(proofDialog.value.preview)URL.revokeObjectURL(proofDialog.value.preview);proofDialog.value={...proofDialog.value,file,preview:URL.createObjectURL(file)}}
const hasBuilding=id=>(data.value.predios||[]).includes(id)
async function buildFor(item){if(saving.value)return;saving.value=true;try{const city=await api('/api/city');await api('/api/city/actions','POST',{type:'build',activity_id:item.id,expected_revision:city.revision,request_id:crypto.randomUUID()});data.value={...data.value,predios:[...(data.value.predios||[]),item.id]};notify(`Prédio "${item.place||item.title}" construído na cidade.`);await refresh()}catch(e){notify(e.message,'error')}finally{saving.value=false}}
async function sendProof(){const dialog=proofDialog.value;if(!dialog||proofSaving.value)return;const note=dialog.note.trim();if(!dialog.file&&note.length<20){notify('Escreva pelo menos 20 caracteres ou envie uma foto.','error');return}proofSaving.value=true;try{const proof={};if(note)proof.note=note;if(dialog.file)proof.photo=await photoToDataUrl(dialog.file);const result=await api(`/api/personal/entries/${encodeURIComponent(dialog.item.id)}/checkin`,'PUT',{done:true,proof});const {proof_result,...rest}=result;data.value={...data.value,...rest};notify(proof_result?.bonus>0?`Comprovado · +${proof_result.bonus} moedas`:proof_result?.reason==='daily_cap'?'Comprovação guardada. O bônus de hoje já foi usado.':'Comprovação atualizada.');if(dialog.preview)URL.revokeObjectURL(dialog.preview);proofDialog.value=null;previousFocus?.focus?.()}catch(e){notify(e.message,'error')}finally{proofSaving.value=false}}
function setOnline(){online.value=navigator.onLine}
function keydown(event){if(event.key==='Escape'){if(proofDialog.value)closeProof();else if(eventDialog.value)closeEvent();else if(projectDialog.value)closeProject();else if(weightDialog.value)closeWeight();else if(modal.value)closeForm();else mobileMenu.value=false}if(event.key==='Tab'&&(modal.value||proofDialog.value||eventDialog.value||projectDialog.value||weightDialog.value)){const root=document.querySelector(proofDialog.value?'.proof-dialog':eventDialog.value||projectDialog.value||weightDialog.value?'.side-dialog':modal.value?'.entry-dialog':'.bridge-dialog');const els=[...root.querySelectorAll('button:not(:disabled),input,select,textarea,iframe,a[href]')];if(event.shiftKey&&document.activeElement===els[0]){event.preventDefault();els.at(-1)?.focus()}else if(!event.shiftKey&&document.activeElement===els.at(-1)){event.preventDefault();els[0]?.focus()}}}
onMounted(()=>{parseRoute();refresh();window.addEventListener('hashchange',parseRoute);window.addEventListener('keydown',keydown);window.addEventListener('online',setOnline);window.addEventListener('offline',setOnline);poll=setInterval(()=>{if(!document.hidden&&!modal.value&&!eventDialog.value&&!projectDialog.value&&!weightDialog.value)refresh()},60000)})
onUnmounted(()=>{clearInterval(poll);clearTimeout(timer);window.removeEventListener('online',setOnline);window.removeEventListener('offline',setOnline);window.removeEventListener('hashchange',parseRoute);window.removeEventListener('keydown',keydown)})
</script>
<template>
<main class="personal-app" :class="{ 'sidebar-compact':collapsed,'mobile-nav-open':mobileMenu }">
  <button v-if="mobileMenu" class="nav-scrim" aria-label="Fechar menu" @click="mobileMenu=false" />
  <aside class="sidebar">
    <a class="personal-brand" href="#/inicio" aria-label="Cityou, seu dia"><span class="personal-mark">c<span>.</span></span><strong>Cityou<span>seu espaço pessoal</span></strong></a>
    <button class="sidebar-toggle" :aria-label="collapsed?'Expandir menu':'Recolher menu'" @click="collapsed=!collapsed"><Icon name="menu" :size="16" /></button>
    <nav aria-label="Funções do Cityou"><div v-for="group in groups" :key="group" class="nav-group"><span class="nav-group-label">{{ group }}</span><a v-for="item in sections.filter(i=>i.group===group)" :key="item.id" :href="`#/${item.id}`" :aria-label="item.label" class="personal-nav-item" :class="{active:route===item.id}" :aria-current="route===item.id?'page':undefined" :title="collapsed?item.label:undefined"><Icon :name="item.icon" :size="19" /><span>{{ item.label }}</span><small v-if="item.id==='tarefas'&&pending.length">{{ pending.length }}</small></a></div></nav>
    <div class="sidebar-bottom"><a href="#/mundo" class="city-link" :class="{active:route==='mundo'}"><span class="city-link-icon"><Icon name="globe" :size="22" /></span><span><strong>Mapa-mundo</strong><small>Suas viagens, passo a passo</small></span><Icon name="arrow" :size="15" /></a><a href="#/cidade" class="city-link" :class="{active:route==='cidade'}"><span class="city-link-icon"><Icon name="city" :size="22" /></span><span><strong>Minha cidade</strong><small>O reflexo do seu progresso</small></span><Icon name="arrow" :size="15" /></a><a href="#/conta" class="profile-link" :class="{active:route==='conta'}"><span class="profile-avatar">{{ (account?.display_name||'C').slice(0,1).toUpperCase() }}</span><span><strong>{{ account?.display_name||'Demonstração' }}</strong><small>{{ account?.email||'Seu espaço, no seu ritmo' }}</small></span><Icon name="settings" :size="17" /></a><button v-if="account" class="sign-out" :disabled="signingOut" @click="leave">{{ signingOut?'Saindo…':'Sair da conta' }}</button><a v-else class="sign-out" href="/?inicio">Criar conta ou entrar</a></div>
  </aside>
  <section class="app-main">
    <header class="personal-topbar"><div class="topbar-left"><button class="mobile-menu icon-btn" aria-label="Abrir menu" @click="mobileMenu=!mobileMenu"><Icon name="menu" /></button><span class="breadcrumb">Meu espaço <Icon name="chevron" :size="13" /><strong>{{ active?.label||(route==='mundo'?'Mapa-mundo':'Minha cidade') }}</strong></span></div><div class="topbar-actions"><span class="local-status" role="status"><i :class="{offline:saveState==='offline',busy:saveState==='saving'}" />{{ {saved:'Salvo',saving:'Salvando…',offline:'Sem conexão'}[saveState] }}</span><button class="icon-btn" aria-label="Atualizar meus dados" :disabled="refreshing" @click="refresh"><Icon name="refresh" :class="{spinning:refreshing}" :size="18" /></button><button class="new-entry" @click="showForm(route==='habitos'?'habit':route==='metas'?'goal':route==='financas'?'transaction':route==='nutricao'?'meal':route==='memorias'||route==='autoconhecimento'?'note':'task')"><Icon name="plus" :size="17" /><span>Novo registro</span></button></div></header>
    <div v-if="error && route !== 'mundo'" class="page-error" role="alert">{{ error }}<button @click="refresh">Tentar novamente</button></div>
    <div v-if="route==='mundo'" class="city-space"><div class="city-space-bar"><span><Icon name="globe" :size="17" />Seu mapa-mundo, em um espaço próprio.</span><a href="/world.html" target="_blank" rel="noopener">Abrir só o mapa <Icon name="arrow" :size="15" /></a></div><iframe src="/world.html" title="Mapa-mundo BuildU" /></div>
    <div v-else-if="route==='cidade'" class="city-space"><div class="city-space-bar"><span><Icon name="city" :size="17" />Sua cidade, em um espaço próprio.</span><a href="/city.html" target="_blank" rel="noopener">Abrir só a cidade <Icon name="arrow" :size="15" /></a></div><iframe src="/city.html" title="Minha cidade Cityou" /></div>
    <div v-else class="personal-content">
      <div class="page-heading"><div><span class="date-caption">{{ shortDate }}</span><h1>{{ route==='inicio'?greeting:active?.label }}</h1><p>{{ route==='inicio'?'Sua vida não precisa caber toda na sua cabeça.':active?.description }}</p></div><span v-if="route==='inicio'" class="greeting-orbit" aria-hidden="true"><i v-for="n in 6" :key="n" :style="{'--petal':n}" /><Icon name="spark" :size="23" /></span></div>
      <div v-if="loading" class="loading-state" role="status"><Icon name="refresh" class="spinning" />Abrindo seu espaço…</div>
      <template v-else-if="route==='inicio'">
        <section class="capture-panel"><span class="capture-symbol"><Icon name="spark" :size="25" /></span><div><h2>O que vamos tirar da sua cabeça?</h2><p>Uma tarefa, uma ideia ou algo que você quer lembrar.</p></div><button class="capture-button" @click="showForm('note')">Anotar <Icon name="plus" :size="17" /></button></section>
        <div class="overview-grid">
          <section class="surface today-panel"><div class="surface-heading"><h2>Seu próximo passo</h2><a href="#/tarefas">Ver tarefas <Icon name="arrow" :size="15" /></a></div><div class="week-strip"><span v-for="d in weeks" :key="d.day" :class="{today:d.today}"><small>{{ d.label }}</small><strong>{{ d.num }}</strong><i v-if="d.today" /></span></div><ul v-if="pending.length" class="personal-task-list"><li v-for="task in pending.slice(0,3)" :key="task.id"><button class="round-check" :aria-label="`Concluir ${task.title}`" :disabled="saving" @click="finish(task)" /><div><strong>{{ task.title }}</strong><small>{{ task.due_date?formatDate(task.due_date):'No seu tempo' }}</small></div><span class="priority-dot" :class="`priority-${task.priority}`" /></li></ul><div v-else class="gentle-empty"><span class="empty-orbit"><Icon name="check" :size="24" /></span><strong>Espaço para o que vem agora.</strong><p>Escolha uma tarefa pequena para começar.</p><button class="inline-button" @click="showForm('task')"><Icon name="plus" :size="15" />Criar uma tarefa</button></div></section>
          <section class="surface day-agenda"><div class="surface-heading"><h2>Na sua agenda</h2><a href="#/agenda" aria-label="Abrir a agenda"><Icon name="arrow" :size="17" /></a></div><div class="agenda-summary"><span class="agenda-day">{{ today().slice(-2) }}</span><div><strong>{{ todayRespiro?'Dia de respiro':`${todayEvents.length} compromisso${todayEvents.length===1?'':'s'}` }}</strong><small>{{ todayRespiro?'Nada a cumprir':'para hoje' }}</small></div><Icon name="calendar" :size="28" /></div><div v-for="event in todayEvents.filter(i=>i.kind!=='respiro').slice(0,2)" :key="event.id" class="small-event"><time>{{ eventTime(event) }}</time><strong>{{ event.title }}</strong><em v-if="event.firmness==='leve'" class="ag-soft">se der</em></div><div v-if="!todayEvents.length" class="agenda-empty"><span class="agenda-doodle" aria-hidden="true"><Icon name="sun" :size="42" /></span><p>Um pouco de espaço livre também faz parte.</p></div><button class="quiet-button full-width" @click="showEvent()"><Icon name="plus" :size="15" />Adicionar compromisso</button></section>
        </div>
        <div class="section-label"><h2>Um pouco melhor, todos os dias</h2><span>Seu ritmo conta.</span></div>
        <div class="area-grid"><a v-for="card in areaCards" :key="card.id" :href="`#/${card.id}`" class="area-card" :class="card.tone"><span class="area-icon"><Icon :name="card.icon" :size="23" /></span><span class="area-kicker">{{ card.title }}</span><strong>{{ card.value }}</strong><small>{{ card.detail }}</small><Icon name="arrow" :size="18" class="area-arrow" /></a></div>
        <section class="reflection-strip"><span class="reflection-icon"><Icon name="heart" :size="22" /></span><div><strong>E você, como está hoje?</strong><span>Uma pausa para perceber. Só isso.</span></div><button class="quiet-button" @click="navigate('autoconhecimento')">Registrar meu momento <Icon name="arrow" :size="15" /></button></section>
      </template>
      <template v-else-if="route==='tarefas'">
        <div class="list-toolbar"><div class="segmented"><button v-for="filter in [{id:'open',label:'A fazer'},{id:'done',label:'Concluídas'},{id:'all',label:'Todas'}]" :key="filter.id" :class="{active:taskFilter===filter.id}" @click="taskFilter=filter.id">{{ filter.label }}</button></div><label class="search-field"><Icon name="search" :size="17" /><input v-model="search" placeholder="Buscar tarefa" aria-label="Buscar tarefa" /></label><button class="primary-btn" @click="showForm('task')"><Icon name="plus" :size="17" />Nova tarefa</button></div><section class="surface"><ul class="personal-task-list full-list"><li v-for="task in shownTasks" :key="task.id"><button class="round-check" :class="{done:task.status==='done'}" :disabled="saving||task.status==='done'" :aria-label="`Concluir ${task.title}`" @click="finish(task)"><Icon v-if="task.status==='done'" name="check" :size="14" /></button><div><strong>{{ task.title }}</strong><small>{{ task.description||'Sem descrição' }}</small></div><span class="task-date">{{ formatDate(task.due_date) }}</span></li></ul><div v-if="!shownTasks.length" class="gentle-empty"><Icon name="tasks" :size="35" /><h2>Nada nesta lista.</h2><p>Adicione o próximo passo quando precisar.</p></div></section>
      </template>
      <template v-else-if="route==='habitos'">
        <div class="habits-summary surface"><span class="habit-ring" :style="{'--progress':habits.length?`${habitsDone/habits.length*100}%`:'0%'}"><strong>{{ habitsDone }}<small>/ {{ habits.length }}</small></strong></span><div><h2>Hoje já conta.</h2><p>{{ habits.length?'Registre o que você fez, sem precisar ser perfeito.':'Escolha algo pequeno o suficiente para caber no dia.' }}</p></div><button class="primary-btn" @click="showForm('habit')"><Icon name="plus" :size="17" />Novo hábito</button></div><div class="record-grid"><article v-for="habit in habits" :key="habit.id" class="surface habit-card" :class="{completed:isDone(habit.id)}"><span class="area-icon mint"><Icon name="habits" :size="24" /></span><h2>{{ habit.title }}</h2><p>{{ habit.body||'Seu passo possível para hoje.' }}</p><small v-if="habit.place" class="place-tag">{{ habit.place }}</small><button class="habit-done" :disabled="saving" :aria-pressed="isDone(habit.id)" @click="toggleHabit(habit)"><Icon :name="isDone(habit.id)?'check':'plus'" :size="18" />{{ isDone(habit.id)?'Feito hoje':'Marcar como feito' }}</button><button type="button" class="proof-button" :disabled="saving" @click="showProof(habit)"><Icon name="spark" :size="15" />Comprovar</button><button v-if="!hasBuilding(habit.id)" type="button" class="proof-button" :disabled="saving" @click="buildFor(habit)"><Icon name="city" :size="15" />Construir na cidade</button><a v-else class="building-tag" href="#/cidade"><Icon name="city" :size="15" />Prédio na cidade</a></article><button class="add-card" @click="showForm('habit')"><Icon name="plus" :size="27" /><strong>Criar meu próximo hábito</strong><span>Comece pequeno.</span></button></div>
      </template>
      <template v-else-if="route==='metas'">
        <div class="list-toolbar"><span class="muted">Um passo concreto por dia. Sem prazo de validade.</span><button class="primary-btn" @click="showForm('goal')"><Icon name="plus" :size="17" />Nova meta</button></div>
        <div class="record-grid"><article v-for="goal in goals" :key="goal.id" class="surface habit-card"><span class="area-icon purple"><Icon name="spark" :size="24" /></span><h2>{{ goal.title }}</h2><p>{{ goal.body }}</p><span class="goal-caption">{{ Math.min(goalCount(goal.id),goal.target) }} / {{ goal.target }} dias com progresso</span><span class="personal-goal-track"><i :style="{transform:`scaleX(${Math.min(1,goalCount(goal.id)/goal.target)})`}" /></span><small v-if="goal.place" class="place-tag">{{ goal.place }}</small><button class="habit-done" :disabled="saving" :aria-pressed="isDone(goal.id)" @click="toggleHabit(goal)"><Icon :name="isDone(goal.id)?'check':'plus'" :size="17" />{{ isDone(goal.id)?'Passo de hoje registrado':'Registrar um passo hoje' }}</button><button type="button" class="proof-button" :disabled="saving" @click="showProof(goal)"><Icon name="spark" :size="15" />Comprovar</button><button v-if="!hasBuilding(goal.id)" type="button" class="proof-button" :disabled="saving" @click="buildFor(goal)"><Icon name="city" :size="15" />Construir na cidade</button><a v-else class="building-tag" href="#/cidade"><Icon name="city" :size="15" />Prédio na cidade</a></article><button class="add-card" @click="showForm('goal')"><Icon name="spark" :size="27" /><strong>Qual é sua próxima conquista?</strong><span>Você define o que importa.</span></button></div>
      </template>
      <template v-else-if="route==='agenda'">
        <div class="ag-bar">
          <div class="ag-month"><button class="ag-icon ag-flip" aria-label="Mês anterior" @click="shiftMonth(-1)"><Icon name="chevron" :size="16" /></button><h2 class="ag-title" aria-live="polite">{{ monthLabel }}</h2><button class="ag-icon" aria-label="Próximo mês" @click="shiftMonth(1)"><Icon name="chevron" :size="16" /></button></div>
          <div class="ag-actions"><button class="ag-btn" :disabled="saving" @click="toggleRespiro(selectedDay)"><Icon name="sun" :size="16" />{{ selectedRespiro?'Tirar o respiro':'Marcar respiro' }}</button><button class="ag-btn ag-primary" @click="showEvent()"><Icon name="plus" :size="16" />Novo compromisso</button></div>
        </div>
        <div class="ag-layout">
          <section class="surface ag-calendar" aria-label="Calendário do mês">
            <div class="ag-weekdays" aria-hidden="true"><span v-for="(letter,i) in ['S','T','Q','Q','S','S','D']" :key="i">{{ letter }}</span></div>
            <div class="ag-grid"><template v-for="(cell,i) in monthCells" :key="i"><span v-if="!cell" class="ag-blank" /><button v-else class="ag-cell" :class="cellClass(cell)" :aria-label="cellLabel(cell)" :aria-pressed="cell.day===selectedDay" @click="selectedDay=cell.day;confirmEvent=''"><b>{{ cell.num }}</b><Icon v-if="cell.events.some(i=>i.kind==='respiro')" name="sun" :size="12" /><span v-else class="ag-dots" aria-hidden="true"><i v-for="e in cell.events.slice(0,3)" :key="e.id" :class="{soft:e.firmness==='leve'}" /></span></button></template></div>
            <p class="ag-legend"><span><i class="dot" />compromisso</span><span><i class="dot soft" />se der</span><span><Icon name="sun" :size="12" />respiro</span></p>
          </section>
          <section class="surface ag-detail" aria-live="polite">
            <div class="surface-heading"><h2>{{ longDay(selectedDay) }}</h2><small v-if="selectedDay===today()" class="ag-chip">hoje</small><small v-else-if="selectedDay<today()" class="ag-chip past">passou</small></div>
            <ul v-if="selectedEvents.length" class="ag-list">
              <li v-for="event in selectedEvents" :key="event.id" :class="{'is-respiro':event.kind==='respiro',soft:event.firmness==='leve'&&event.kind!=='respiro',past:selectedDay<today()}">
                <time>{{ eventTime(event) }}</time>
                <div><strong>{{ event.title }}</strong><small v-if="event.kind==='respiro'">Nada a cumprir</small><small v-else-if="event.place">{{ event.place }}</small><em v-if="event.kind!=='respiro'&&event.firmness==='leve'" class="ag-soft">se der</em><p v-if="event.notes">{{ event.notes }}</p></div>
                <span class="ag-row-actions"><button v-if="event.kind!=='respiro'" class="ag-link" @click="showEvent(event)">Editar</button><button class="ag-link" :disabled="saving" @click="event.kind==='respiro'?toggleRespiro(event.day):dropEvent(event)">{{ confirmEvent===event.id?'Apagar mesmo?':event.kind==='respiro'?'Tirar':'Apagar' }}</button></span>
              </li>
            </ul>
            <div v-else class="gentle-empty"><span class="agenda-doodle" aria-hidden="true"><Icon name="sun" :size="38" /></span><p>Um pouco de espaço livre também faz parte.</p></div>
          </section>
        </div>
      </template>

      <template v-else-if="route==='financas'">
        <div class="finance-stats"><article class="surface"><span>Entradas do mês</span><strong class="mint-text">{{ money(income) }}</strong><Icon name="down" :size="20" /></article><article class="surface"><span>Saídas do mês</span><strong class="peach-text">{{ money(expenses) }}</strong><Icon name="up" :size="20" /></article><article class="surface"><span>Saldo dos registros</span><strong>{{ money(income-expenses) }}</strong><Icon name="finance" :size="20" /></article></div><div class="list-toolbar"><h2>Seus lançamentos</h2><button class="primary-btn" @click="showForm('transaction')"><Icon name="plus" :size="17" />Novo lançamento</button></div><section class="surface"><div v-for="item in transactions" :key="item.id" class="transaction-row"><span class="transaction-icon" :class="item.direction"><Icon :name="item.direction==='income'?'down':'up'" :size="18" /></span><div><strong>{{ item.title }}</strong><small>{{ formatDate(item.day) }} · {{ item.category }}</small></div><strong :class="item.direction==='income'?'mint-text':'peach-text'">{{ item.direction==='income'?'+':'−' }} {{ money(item.amount_cents) }}</strong></div><div v-if="!transactions.length" class="gentle-empty"><Icon name="finance" :size="36" /><h2>Comece com um lançamento.</h2><p>Este saldo considera apenas os registros deste novo espaço.<br />Suas planilhas anteriores continuam disponíveis.</p><button class="inline-button" @click="showForm('transaction')">Adicionar entrada ou saída <Icon name="plus" :size="15" /></button></div></section>
      </template>
      <template v-else-if="route==='fitness'">
        <section class="surface wt-hero"><span class="area-icon peach"><Icon name="fitness" :size="30" /></span><div><span class="eyebrow">SEU RITMO, SEM META</span><h2>Um número de cada vez.</h2><p>O peso oscila ao longo do dia. A média de 7 dias mostra o ritmo, sem julgamento.</p></div><button class="ag-btn ag-primary" @click="showWeight()"><Icon name="plus" :size="16" />Registrar peso do dia</button></section>
        <div class="finance-stats"><article class="surface"><span>Última pesagem</span><strong>{{ weights.length?`${kg(weights[0].grams)} kg`:'Ainda sem registro' }}</strong></article><article class="surface"><span>Média de 7 dias</span><strong>{{ latestTrend?`${kg(latestTrend.avg_grams)} kg`:'—' }}</strong></article><article class="surface"><span>Pesagens nos últimos 120 dias</span><strong>{{ weights.length }}</strong></article></div>
        <section class="surface wt-chart"><div class="surface-heading"><h2>Sua trajetória</h2></div>
          <p class="wt-trend" role="status">{{ trendText }}</p>
          <figure v-if="chart" class="wt-figure"><svg :viewBox="`0 0 ${chart.W} ${chart.H}`" role="img" :aria-label="chart.label"><line x1="8" :x2="chart.W-8" :y1="chart.H-20" :y2="chart.H-20" class="wt-axis" /><circle v-for="dot in chart.dots" :key="dot.day" :cx="dot.cx" :cy="dot.cy" r="2.6" class="wt-dot" /><path :d="chart.line" class="wt-avg" /></svg><figcaption><span>{{ formatDate(chart.from) }}</span><span class="wt-legend"><i class="wt-key dot" />pesagem<i class="wt-key line" />média de 7 dias</span><span>{{ formatDate(chart.to) }}</span></figcaption></figure>
          <div v-else class="gentle-empty"><Icon name="fitness" :size="32" /><p>Seu gráfico começa com a primeira pesagem.</p></div>
        </section>
        <section v-if="weights.length" class="surface wt-list"><div class="surface-heading"><h2>Suas pesagens</h2></div><ul><li v-for="weight in weights" :key="weight.id"><time>{{ formatDate(weight.day) }}</time><strong>{{ kg(weight.grams) }} kg</strong><small v-if="weight.note">{{ weight.note }}</small><span class="ag-row-actions"><button class="ag-link" @click="showWeight(weight)">Editar</button><button class="ag-link" :disabled="saving" @click="dropWeight(weight)">{{ confirmWeight===weight.id?'Apagar mesmo?':'Apagar' }}</button></span></li></ul></section>
      </template>
      <template v-else-if="route==='nutricao'">
        <section class="nutrition-banner surface"><span class="nutrition-art" aria-hidden="true"><i /><i /><i /></span><div><span class="eyebrow">UM OLHAR PARA SUA ALIMENTAÇÃO</span><h2>Primeiro, conhecer sua rotina.</h2><p>Registre refeições, horários e quantidades. Nenhum nutriente é estimado sem informação suficiente.</p><button class="primary-btn" @click="showForm('meal')"><Icon name="plus" :size="17" />Registrar refeição</button></div></section><div class="record-grid"><article v-for="item in entryList('meal')" :key="item.id" class="surface note-card"><span class="eyebrow">{{ formatDate(item.day) }}</span><h2>{{ item.title }}</h2><p>{{ item.body }}</p></article></div>
      </template>
      <template v-else-if="route==='autoconhecimento'">
        <section class="reflection-hero surface"><span class="reflection-bloom" aria-hidden="true"><i v-for="n in 5" :key="n" :style="{'--petal':n}" /></span><div><span class="eyebrow">UMA CONVERSA COM VOCÊ</span><h2>Como está sendo o seu dia?</h2><p>Escreva o que sente, o que funcionou ou o que está difícil.</p><div class="hero-actions"><button class="primary-btn" @click="showForm('note')">Registrar meu momento <Icon name="plus" :size="17" /></button></div></div></section><div class="section-label"><h2>Seus registros</h2><a href="#/memorias">Ver memórias <Icon name="arrow" :size="15" /></a></div><div class="record-grid"><article v-for="note in notes.slice(0,6)" :key="note.id" class="surface note-card"><span class="eyebrow">{{ formatDate(note.day) }}</span><h2>{{ note.title }}</h2><p>{{ note.body }}</p></article></div><p v-if="!notes.length" class="small-note">Você escolhe o que compartilhar. Só você vê o que escreve aqui.</p>
      </template>
      <template v-else-if="route==='biblioteca'||route==='estudos'">
<section class="surface gentle-empty soon"><Icon name="library" :size="40" /><h2>{{ route==='estudos'?'Estudos':'Biblioteca' }}, em breve.</h2><p>Seus materiais vão ficar sempre por perto, neste mesmo lugar.</p></section>
      </template>
      <template v-else-if="route==='projetos'">
        <div class="list-toolbar"><div class="segmented"><button :class="{active:projectView==='active'}" @click="projectView='active'">Em andamento <small>{{ activeCount }}</small></button><button :class="{active:projectView==='archived'}" @click="projectView='archived'">Guardados <small>{{ savedCount }}</small></button></div><button class="primary-btn" @click="showProject()"><Icon name="plus" :size="17" />Novo projeto</button></div>
        <div class="record-grid"><article v-for="project in shownProjects" :key="project.id" class="surface pj-card" :class="{saved:project.status==='archived'}">
          <span class="project-cover"><Icon name="projects" :size="34" /><i /><i /></span>
          <h2>{{ project.name }}</h2><p v-if="project.description" class="pj-desc">{{ project.description }}</p>
          <p v-if="project.steps_done" class="pj-count">{{ stepsLabel(project.steps_done) }}</p>
          <template v-if="project.status==='active'">
            <label class="pj-step"><span>{{ stepPrompt(project) }}</span><input :value="draftOf(project)" maxlength="180" placeholder="Um passo pequeno o bastante para começar" @input="stepDrafts={...stepDrafts,[project.id]:$event.target.value}" @keydown.enter.prevent="draftOf(project).trim()&&dirtyStep(project)&&saveStep(project)" /></label>
            <div class="pj-actions"><button v-if="dirtyStep(project)" class="ag-btn ag-primary" :disabled="saving||!draftOf(project).trim()" @click="saveStep(project)">Guardar passo</button><button v-else-if="project.next_step" class="ag-btn ag-primary" :disabled="saving" @click="finishStep(project)"><Icon name="check" :size="16" />Concluí</button></div>
          </template>
          <p v-else class="pj-count">{{ project.next_step?`Próximo passo: ${project.next_step}`:'Sem passo definido.' }}</p>
          <div class="pj-foot"><button class="ag-link" @click="showProject(project)">Editar</button><button class="ag-link" :disabled="saving" @click="setProjectStatus(project,project.status==='active'?'archived':'active')">{{ project.status==='active'?'Guardar por enquanto':'Retomar' }}</button><button class="ag-link" :disabled="saving" @click="dropProject(project)">{{ confirmProject===project.id?'Apagar mesmo?':'Apagar' }}</button></div>
        </article></div>
        <div v-if="!shownProjects.length" class="surface gentle-empty"><Icon name="projects" :size="40" /><h2>{{ projectView==='active'?'Seu próximo projeto tem espaço aqui.':'Nada guardado por enquanto.' }}</h2><p v-if="projectView==='active'">Um nome e um passo: é o suficiente para começar.</p><button v-if="projectView==='active'" class="inline-button" @click="showProject()">Criar um projeto <Icon name="plus" :size="15" /></button></div>
      </template>
      <template v-else-if="route==='memorias'">
        <div class="list-toolbar"><span class="muted">Suas anotações e o contexto que você já compartilhou.</span><button class="primary-btn" @click="showForm('note')"><Icon name="plus" :size="17" />Nova memória</button></div><div class="record-grid"><article v-for="note in notes" :key="note.id" class="surface note-card"><span class="eyebrow">{{ formatDate(note.day) }} · NOVO ESPAÇO</span><h2>{{ note.title }}</h2><p>{{ note.body }}</p></article></div><div v-if="!notes.length" class="surface gentle-empty"><Icon name="note" :size="38" /><h2>Guarde uma ideia.</h2><p>Você pode começar com uma frase.</p></div>
      </template>
      <template v-else-if="route==='conta'">
        <section class="surface account-panel"><span class="profile-avatar large">{{ (account?.display_name||'C').slice(0,1).toUpperCase() }}</span><div><h2>{{ account?.display_name||'Demonstração' }}</h2><p>{{ account?.email||'Este espaço está guardado só neste navegador.' }}</p></div><button v-if="account" class="primary-btn" :disabled="signingOut" @click="leave">{{ signingOut?'Saindo…':'Sair da conta' }}</button><a v-else class="primary-btn" href="/?inicio">Criar conta para guardar</a></section>
        <p class="small-note">{{ account?'Seus registros ficam guardados na sua conta.':'Sem conta, tudo expira em 30 dias. Criar uma conta leva o que você já fez junto.' }}</p>
      </template>
    </div>
  </section>

  <Transition name="notice"><div v-if="notice" class="personal-notice" :class="notice.kind" role="status"><Icon :name="notice.kind==='error'?'close':'check'" :size="18" /><span>{{ notice.text }}</span><button class="icon-btn" aria-label="Fechar aviso" @click="notice=''"><Icon name="close" :size="15" /></button></div></Transition>
  <div v-if="modal" class="personal-overlay" @click.self="closeForm"><form class="entry-dialog" role="dialog" aria-modal="true" aria-labelledby="entry-title" @submit.prevent="save"><header><span class="dialog-icon"><Icon :name="modal==='task'?'tasks':modal==='habit'?'habits':modal==='goal'?'spark':modal==='transaction'?'finance':modal==='meal'?'nutrition':'note'" :size="23" /></span><button type="button" class="icon-btn" aria-label="Fechar formulário" :disabled="saving" @click="closeForm"><Icon name="close" /></button></header><h2 id="entry-title">{{ {task:'Um próximo passo.',habit:'Um hábito possível.',goal:'Uma conquista de cada vez.',note:'Tire da cabeça.',transaction:'Seu dinheiro, com clareza.',meal:'O que teve no prato?'}[modal] }}</h2><label>{{ modal==='task'?'O que você quer fazer?':modal==='habit'?'Qual hábito quer cultivar?':'Título' }}<input v-model="form.title" required maxlength="180" :placeholder="modal==='habit'?'Algo que caiba em dois minutos':'Escreva aqui'" /></label><label v-if="['habit','goal','task'].includes(modal)">Área<select v-model="form.domain"><option v-for="[id,name] in domains" :key="id" :value="id">{{ name }}</option></select></label><label v-if="['habit','goal','task'].includes(modal)">Local ou atividade, se houver<input v-model="form.place" maxlength="80" placeholder="Ex.: Academia Central" /></label><label v-if="modal==='task'">Prazo, se houver<input v-model="form.due_date" type="date" /></label><template v-else><div v-if="modal==='transaction'" class="form-columns"><label>Tipo<select v-model="form.direction" aria-label="Tipo"><option value="expense">Saída</option><option value="income">Entrada</option></select></label><label>Valor em R$<input v-model="form.amount" type="text" inputmode="decimal" placeholder="0,00" required /></label></div><label v-if="modal==='transaction'">Categoria<input v-model="form.category" maxlength="50" /></label><label>{{ modal==='meal'?'Alimentos e quantidades':'Detalhes, se quiser' }}<textarea v-model="form.body" rows="4" maxlength="4000" :placeholder="modal==='meal'?'O que comeu, como foi preparado e qual a quantidade aproximada':'Deixe aqui o que importa para você.'" /></label><label v-if="modal==='goal'">Quantos dias com um passo concreto?<input v-model="form.target" type="number" min="1" max="10000" required /></label><label>Data<input v-model="form.day" required type="date" /></label></template><footer><button type="button" class="quiet-button" :disabled="saving" @click="closeForm">Agora não</button><button class="primary-btn" :disabled="saving">{{ saving?'Salvando…':'Guardar' }}<Icon name="check" :size="16" /></button></footer></form></div>
  <div v-if="eventDialog" class="personal-overlay" @click.self="closeEvent"><form class="entry-dialog side-dialog event-dialog" role="dialog" aria-modal="true" aria-labelledby="event-title" @submit.prevent="saveEvent"><header><span class="dialog-icon"><Icon name="calendar" :size="23" /></span><button type="button" class="icon-btn" aria-label="Fechar formulário" :disabled="saving" @click="closeEvent"><Icon name="close" /></button></header><h2 id="event-title">{{ eventDialog.id?'Ajustar o compromisso.':'Um compromisso, sem pressa.' }}</h2><label>O que vai acontecer?<input v-model="eventDialog.title" required maxlength="180" placeholder="Escreva aqui" /></label><label>Dia<input v-model="eventDialog.day" required type="date" min="2000-01-01" max="2100-12-31" /></label><div class="form-columns"><label>Início, se houver<input v-model="eventDialog.start_time" type="time" /></label><label>Fim<input v-model="eventDialog.end_time" type="time" :disabled="!eventDialog.start_time" /></label></div><label>Firmeza<select v-model="eventDialog.firmness"><option value="firme">Firme: está combinado</option><option value="leve">Leve: se der</option></select></label><label>Local, se houver<input v-model="eventDialog.place" maxlength="80" /></label><label>Notas, se quiser<textarea v-model="eventDialog.notes" rows="3" maxlength="1000" /></label><footer><button type="button" class="quiet-button" :disabled="saving" @click="closeEvent">Agora não</button><button class="primary-btn" :disabled="saving">{{ saving?'Salvando…':'Guardar' }}<Icon name="check" :size="16" /></button></footer></form></div>
  <div v-if="projectDialog" class="personal-overlay" @click.self="closeProject"><form class="entry-dialog side-dialog" role="dialog" aria-modal="true" aria-labelledby="project-title" @submit.prevent="saveProject"><header><span class="dialog-icon"><Icon name="projects" :size="23" /></span><button type="button" class="icon-btn" aria-label="Fechar formulário" :disabled="saving" @click="closeProject"><Icon name="close" /></button></header><h2 id="project-title">{{ projectDialog.id?'Ajustar o projeto.':'Um projeto, um passo.' }}</h2><label>Como se chama?<input v-model="projectDialog.name" required maxlength="120" placeholder="Escreva aqui" /></label><label>Detalhes, se quiser<textarea v-model="projectDialog.description" rows="3" maxlength="1000" /></label><label v-if="!projectDialog.id">Qual é o próximo passo? (pode deixar para depois)<input v-model="projectDialog.next_step" maxlength="180" /></label><footer><button type="button" class="quiet-button" :disabled="saving" @click="closeProject">Agora não</button><button class="primary-btn" :disabled="saving">{{ saving?'Salvando…':'Guardar' }}<Icon name="check" :size="16" /></button></footer></form></div>
  <div v-if="weightDialog" class="personal-overlay" @click.self="closeWeight"><form class="entry-dialog side-dialog" role="dialog" aria-modal="true" aria-labelledby="weight-title" @submit.prevent="saveWeight"><header><span class="dialog-icon"><Icon name="fitness" :size="23" /></span><button type="button" class="icon-btn" aria-label="Fechar formulário" :disabled="saving" @click="closeWeight"><Icon name="close" /></button></header><h2 id="weight-title">{{ weightDialog.id?'Ajustar a pesagem.':'Peso do dia.' }}</h2><label>Quanto marcou, em kg?<input v-model="weightDialog.kg" required inputmode="decimal" placeholder="Ex.: 70,5" /></label><label>Dia<input v-model="weightDialog.day" type="date" required :min="weightMinDay()" :max="today()" :disabled="Boolean(weightDialog.id)" /></label><label>Nota, se quiser<input v-model="weightDialog.note" maxlength="200" placeholder="Ex.: depois do café" /></label><footer><button type="button" class="quiet-button" :disabled="saving" @click="closeWeight">Agora não</button><button class="primary-btn" :disabled="saving">{{ saving?'Salvando…':'Guardar' }}<Icon name="check" :size="16" /></button></footer></form></div>
  <div v-if="proofDialog" class="personal-overlay" @click.self="closeProof"><form class="entry-dialog proof-dialog" role="dialog" aria-modal="true" aria-labelledby="proof-title" @submit.prevent="sendProof"><header><span class="dialog-icon"><Icon name="check" :size="23" /></span><button type="button" class="icon-btn" aria-label="Fechar comprovação" :disabled="proofSaving" @click="closeProof"><Icon name="close" /></button></header><h2 id="proof-title">Comprovar: {{ proofDialog.item.title }}</h2><p class="proof-help">Opcional. Um relato ou uma foto rende +5 moedas, até 3 por dia. Só você vê. Marcar sem comprovar continua valendo.</p><label>O que você fez?<textarea v-model="proofDialog.note" rows="4" maxlength="500" placeholder="Pelo menos 20 caracteres, ou envie uma foto" /></label><label class="photo-field">Foto, se quiser<input type="file" accept="image/*" capture="environment" @change="pickPhoto" /></label><img v-if="proofDialog.preview" class="proof-preview" :src="proofDialog.preview" alt="Prévia da foto escolhida" /><footer><button type="button" class="quiet-button" :disabled="proofSaving" @click="closeProof">Agora não</button><button class="primary-btn" :disabled="proofSaving">{{ proofSaving?'Enviando…':'Guardar comprovação' }}<Icon name="check" :size="16" /></button></footer></form></div>
</main>
</template>
